shell_commands:
/bin/zsh -lc "cat > src/orchestration/tools/registry.recovery.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#2
it('reports the expected type and path for invalid input', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'forecast', inputSchema: {type: 'object', properties: {location: {type: 'string'}}}},
    async () => 'ok'
  );
  expect(await registry.execute('weather', {location: 42})).toEqual({
    result: expect.stringMatching(/\\/location.*string/),
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.recovery.test.ts"

/bin/zsh -lc "cat > src/orchestration/tools/registry.recovery.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#1
it('reports the full path of a missing nested property', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'forecast', inputSchema: {type: 'object', properties: {address: {type: 'object', required: ['location']}}}},
    async () => 'ok'
  );
  expect(await registry.execute('weather', {address: {}})).toEqual({
    result: expect.stringMatching(/\\/address\\/location.*required/),
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.recovery.test.ts"
